mapper.select:
SELECT 
FROM ydsz_flow_instance
WHERE tenant_id = #{tenantId}
  AND business_type = #{businessType}
  AND business_id = #{businessId}
  AND flow_status IN ('RUNNING', 'SUSPENDED')
  AND status = 'ENABLED'
  AND deleted = 0
LIMIT 1

SELECT FROM ydsz_flow_instance WHERE initiator_id = #{initiatorId}
AND flow_status = #{flowStatus}
AND status = 'ENABLED' AND deleted = 0 ORDER BY start_at DESC

SELECT 
FROM ydsz_flow_instance
WHERE status = 'ENABLED'
  AND deleted = 0

    AND business_type = #{businessType}


    AND initiator_id = #{initiatorId}


    AND flow_status = #{flowStatus}


    AND start_at >= #{startTime}


    AND start_at <= #{endTime}


    AND tenant_id = #{tenantId}



    AND ${dataScopeFilter}

ORDER BY start_at DESC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(1)
FROM ydsz_flow_instance
WHERE status = 'ENABLED'
  AND deleted = 0

    AND business_type = #{businessType}


    AND initiator_id = #{initiatorId}


    AND flow_status = #{flowStatus}


    AND start_at >= #{startTime}


    AND start_at <= #{endTime}


    AND tenant_id = #{tenantId}



    AND ${dataScopeFilter}

SELECT flow_code AS "flowCode",
       MAX(flow_name) AS "flowName",
       COUNT(1) AS "cnt"
FROM ydsz_flow_instance
WHERE status = 'ENABLED' AND deleted = 0
  AND tenant_id = #{tenantId}
  AND start_at >= #{startTime}
  AND start_at <= #{endTime}
GROUP BY flow_code
ORDER BY cnt DESC

SELECT DATE(start_at) AS "date", COUNT(1) AS "newCount"
FROM ydsz_flow_instance
WHERE status = 'ENABLED' AND deleted = 0
  AND start_at IS NOT NULL
  AND tenant_id = #{tenantId}
  AND start_at >= #{startTime}
  AND start_at <= #{endTime}
GROUP BY DATE(start_at)
ORDER BY DATE(start_at) ASC

SELECT DATE(end_at) AS "date", COUNT(1) AS "completedCount"
FROM ydsz_flow_instance
WHERE status = 'ENABLED' AND deleted = 0
  AND end_at IS NOT NULL
  AND tenant_id = #{tenantId}
  AND end_at >= #{startTime}
  AND end_at <= #{endTime}
GROUP BY DATE(end_at)
ORDER BY DATE(end_at) ASC
